import { z } from "zod";

import { attachment, contentPart, localFolder, projectReference } from "@/contracts/api";
import { studioReferenceSchema } from "@/lib/studioReferences";
import { apiURL } from "@/state/apiBase";
import { useDraftStore, type DraftContent } from "@/state/draftStore";
import { useSessionDraftStore, queuedDraftKey, type SessionDraft } from "@/state/sessionDraftStore";

const uploadedAttachment = z.object({
  id: z.string().min(1), name: z.string(), size: z.number(),
  status: z.literal("uploaded"), attachment,
});
const savedContent = z.object({
  text: z.string(),
  attachments: z.array(uploadedAttachment),
  localFolders: z.array(localFolder),
  projectReferences: z.array(projectReference).default([]),
  studioReferences: z.array(studioReferenceSchema).default([]),
  partOrder: z.array(z.object({ type: z.enum(["attachment", "local_folder", "project_reference"]), id: z.string() })),
});
const sessionContent = savedContent.extend({ clientMessageID: z.string().min(1) });
const savedSession = sessionContent.extend({ submission: sessionContent.optional() });
const savedDraft = savedContent.extend({ submission: z.object({
  clientRequestID: z.string().min(1), clientMessageID: z.string().min(1),
  input: z.object({
    text: z.string(), parts: z.array(contentPart), provider: z.string(), model: z.string(),
    projectID: z.string().optional(), widgetDraft: z.string().optional(),
    reasoningEffort: z.string(), title: z.string(),
  }),
  snapshot: savedContent,
}).optional() });

type SavedContent = z.infer<typeof savedContent>;
type Content = DraftContent | SessionDraft;

// Persist server references only. File objects, blob previews and unfinished
// uploads belong to this renderer and cannot be restored after restarting it.
function projectContent(draft: Content): SavedContent {
  const attachments = draft.attachments.filter((item) => item.status === "uploaded" && item.attachment);
  const projectReferences = "projectReferences" in draft ? draft.projectReferences : [];
  const remaining = {
    attachment: new Set(attachments.map((item) => item.id)),
    local_folder: new Set(draft.localFolders.map((item) => item.id)),
    project_reference: new Set(projectReferences.map((item) => item.id)),
  };
  return savedContent.parse({
    text: draft.text, attachments, localFolders: draft.localFolders, projectReferences,
    studioReferences: "studioReferences" in draft ? draft.studioReferences : [],
    partOrder: draft.partOrder.filter((item) => remaining[item.type].has(item.id)),
  });
}

function hasContent(draft: SavedContent) {
  return draft.text !== "" || draft.attachments.length > 0 || draft.localFolders.length > 0 ||
    draft.projectReferences.length > 0 || draft.studioReferences.length > 0;
}

function encodeSession(draft: SessionDraft | undefined, keepEmpty: boolean) {
  if (!draft) return;
  const content = projectContent(draft);
  if (!hasContent(content) && !draft.submission && !keepEmpty) return;
  return JSON.stringify({ ...content, clientMessageID: draft.clientMessageID,
    submission: draft.submission && { ...projectContent(draft.submission), clientMessageID: draft.submission.clientMessageID },
  });
}

function encodeDraft(draft: DraftContent | undefined) {
  if (!draft) return;
  const content = projectContent(draft);
  if (!hasContent(content) && !draft.submission) return;
  return JSON.stringify({ ...content, submission: draft.submission && {
    ...draft.submission, snapshot: projectContent(draft.submission.snapshot),
  } });
}

// Submission acknowledgements compare immutable list-entry identities. Reuse
// matching entries after JSON decoding so unchanged retries keep their IDs and
// acknowledgements still remove only the content actually submitted.
function relinkSnapshot(current: SavedContent, snapshot: SavedContent) {
  const share = <T,>(items: T[], previous: T[]) => {
    const matches = new Map(items.map((item) => [JSON.stringify(item), item]));
    return previous.map((item) => matches.get(JSON.stringify(item)) ?? item);
  };
  snapshot.attachments = share(current.attachments, snapshot.attachments);
  snapshot.localFolders = share(current.localFolders, snapshot.localFolders);
  snapshot.projectReferences = share(current.projectReferences, snapshot.projectReferences);
  snapshot.studioReferences = share(current.studioReferences, snapshot.studioReferences);
  snapshot.partOrder = share(current.partOrder, snapshot.partOrder);
}

let disposeCurrent: (() => void) | undefined;

// Start after the API endpoint is configured and before mounting either app.
// Each draft has its own key: another window editing a different conversation
// must not overwrite it with an older snapshot of the entire draft collection.
export function startDraftPersistence() {
  disposeCurrent?.();
  let storage: Storage;
  try { storage = window.localStorage; } catch { return () => {}; }
  const endpoint = new URL(apiURL("/"), window.location.href);
  const prefix = `pudding.drafts.v1:${encodeURIComponent(endpoint.origin + endpoint.pathname)}:`;
  const sessions: Record<string, SessionDraft> = {};
  const drafts: Record<string, DraftContent> = {};
  const queueEdits: Record<string, string> = {};
  try {
    for (let i = 0; i < storage.length; i++) {
      const key = storage.key(i);
      if (!key?.startsWith(prefix)) continue;
      try {
        const [kind, id] = z.tuple([z.enum(["session", "draft", "queue"]), z.string()]).parse(JSON.parse(key.slice(prefix.length)));
        const value: unknown = JSON.parse(storage.getItem(key) || "null");
        if (kind === "session") {
          const draft = savedSession.parse(value);
          if (draft.submission) relinkSnapshot(draft, draft.submission);
          Object.defineProperty(sessions, id, { value: draft, enumerable: true, configurable: true, writable: true });
        } else if (kind === "draft") {
          const draft = savedDraft.parse(value);
          if (draft.submission) relinkSnapshot(draft, draft.submission.snapshot);
          Object.defineProperty(drafts, id, { value: draft, enumerable: true, configurable: true, writable: true });
        } else {
          Object.defineProperty(queueEdits, id, { value: z.string().min(1).parse(value), enumerable: true, configurable: true, writable: true });
        }
      } catch { /* A damaged entry must not prevent other drafts from loading. */ }
    }
  } catch { return () => {}; }
  for (const [sessionID, inputID] of Object.entries(queueEdits)) {
    if (!Object.hasOwn(sessions, queuedDraftKey(sessionID, inputID))) delete queueEdits[sessionID];
  }
  useSessionDraftStore.setState({ drafts: sessions, queueEdits });
  useDraftStore.setState({ drafts });

  const pending = new Map<string, () => string | undefined>();
  let timer: ReturnType<typeof setTimeout> | undefined;
  const flush = () => {
    clearTimeout(timer); timer = undefined;
    for (const [key, encode] of pending) {
      try {
        const value = encode();
        if (value === undefined) storage.removeItem(key);
        else storage.setItem(key, value);
        pending.delete(key);
      } catch { /* Keep the in-memory draft and retry on the next flush. */ }
    }
  };
  const enqueue = (kind: string, id: string, encode: () => string | undefined) => {
    pending.set(prefix + JSON.stringify([kind, id]), encode);
  };
  const changedKeys = <T,>(next: Record<string, T>, previous: Record<string, T>) =>
    [...new Set([...Object.keys(next), ...Object.keys(previous)])].filter((key) => next[key] !== previous[key]);
  const schedule = (immediate: boolean) => {
    if (immediate) flush();
    else { clearTimeout(timer); timer = setTimeout(flush, 250); }
  };
  const unsubscribeSession = useSessionDraftStore.subscribe((next, previous) => {
    let immediate = false;
    for (const key of changedKeys(next.drafts, previous.drafts)) {
      const draft = next.drafts[key], old = previous.drafts[key];
      const keepEmpty = Object.entries(next.queueEdits).some(([sid, id]) => id && queuedDraftKey(sid, id) === key);
      enqueue("session", key, () => encodeSession(draft, keepEmpty));
      immediate ||= !draft || draft.text === "" || draft.submission !== old?.submission || draft.attachments !== old?.attachments;
    }
    for (const key of changedKeys(next.queueEdits, previous.queueEdits)) {
      const inputID = next.queueEdits[key];
      enqueue("queue", key, () => inputID ? JSON.stringify(inputID) : undefined);
      immediate = true;
    }
    if (pending.size) schedule(immediate);
  });
  const unsubscribeDraft = useDraftStore.subscribe((next, previous) => {
    let immediate = false;
    for (const key of changedKeys(next.drafts, previous.drafts)) {
      const draft = next.drafts[key], old = previous.drafts[key];
      enqueue("draft", key, () => encodeDraft(draft));
      immediate ||= !draft || draft.text === "" || draft.submission !== old?.submission || draft.attachments !== old?.attachments;
    }
    if (pending.size) schedule(immediate);
  });
  const onVisibility = () => { if (document.visibilityState === "hidden") flush(); };
  window.addEventListener("pagehide", flush);
  document.addEventListener("visibilitychange", onVisibility);
  const dispose = () => {
    flush(); unsubscribeSession(); unsubscribeDraft();
    window.removeEventListener("pagehide", flush);
    document.removeEventListener("visibilitychange", onVisibility);
    if (disposeCurrent === dispose) disposeCurrent = undefined;
  };
  disposeCurrent = dispose;
  return dispose;
}

if (import.meta.hot) import.meta.hot.dispose(() => disposeCurrent?.());

