import { create } from "zustand";

import type { ContentPart } from "@/api/client";
import type { DraftAttachment } from "@/lib/attachmentUploads";
import { newClientID } from "@/lib/id";
import type { LocalFolderPath } from "@/lib/localFolders";
import type { DraftPartOrderItem } from "@/lib/submitParts";

export type DraftModelValue = { provider?: string; model?: string };
export type { DraftAttachment } from "@/lib/attachmentUploads";

type DraftListUpdate<T> = T[] | ((current: T[]) => T[]);

export type DraftSubmitInput = {
  text: string;
  parts: ContentPart[];
  provider: string;
  model: string;
  projectID?: string;
  widgetDraft?: string;
  reasoningEffort: string;
  title: string;
};
export type DraftSubmission = {
  clientRequestID: string;
  clientMessageID: string;
  input: DraftSubmitInput;
  snapshot: Omit<DraftContent, "submission">;
};

export type DraftContent = {
  attachments: DraftAttachment[];
  localFolders: LocalFolderPath[];
  partOrder: DraftPartOrderItem[];
  text: string;
  submission?: DraftSubmission;
};

type DraftState = {
  drafts: Record<string, DraftContent>;
  model: DraftModelValue;
  setAttachments: (key: string, update: DraftListUpdate<DraftAttachment>) => void;
  setLocalFolders: (key: string, update: DraftListUpdate<LocalFolderPath>) => void;
  setPartOrder: (key: string, update: DraftListUpdate<DraftPartOrderItem>) => void;
  setText: (key: string, text: string) => void;
  setModel: (model: DraftModelValue) => void;
  clear: (key: string) => void;
  prepareSubmission: (key: string, input: DraftSubmitInput) => DraftSubmission;
  acknowledgeSubmission: (key: string, submission: DraftSubmission) => DraftContent | undefined;
};

export const defaultDraftKey = "chat";
export const widgetDraftKey = (itemID: string) => `widget:${itemID}`;
export const emptyDraftContent: DraftContent = { attachments: [], localFolders: [], partOrder: [], text: "" };

const LAST_MODEL_STORAGE_KEY = "pudding.lastModel";

function readLastModel(): DraftModelValue {
  if (typeof window === "undefined") {
    return {};
  }
  try {
    const raw = window.localStorage.getItem(LAST_MODEL_STORAGE_KEY);
    if (!raw) {
      return {};
    }
    const parsed = JSON.parse(raw) as DraftModelValue;
    if (typeof parsed.provider === "string" && typeof parsed.model === "string" && parsed.provider && parsed.model) {
      return { provider: parsed.provider, model: parsed.model };
    }
  } catch {
    // localStorage 可能被禁用;draft 继续使用内存态。
  }
  return {};
}

function writeLastModel(model: DraftModelValue) {
  if (typeof window === "undefined") {
    return;
  }
  try {
    if (model.provider && model.model) {
      window.localStorage.setItem(LAST_MODEL_STORAGE_KEY, JSON.stringify({ provider: model.provider, model: model.model }));
      return;
    }
    window.localStorage.removeItem(LAST_MODEL_STORAGE_KEY);
  } catch {
    // 忽略持久化失败。
  }
}

// 新会话的本地草稿。持久化由 draftPersistence 处理，提交成功只清理本次快照。
export const useDraftStore = create<DraftState>((set, get) => ({
  drafts: {},
  model: readLastModel(),
  setAttachments: (key, update) => set((state) => {
    const current = state.drafts[key] || emptyDraftContent;
    const attachments = applyDraftListUpdate(current.attachments, update);
    if (attachments === current.attachments) return state;
    return { drafts: { ...state.drafts, [key]: { ...current, attachments } } };
  }),
  setLocalFolders: (key, update) => set((state) => ({ drafts: { ...state.drafts, [key]: { ...(state.drafts[key] || emptyDraftContent), localFolders: applyDraftListUpdate(state.drafts[key]?.localFolders || [], update) } } })),
  setPartOrder: (key, update) => set((state) => ({ drafts: { ...state.drafts, [key]: { ...(state.drafts[key] || emptyDraftContent), partOrder: applyDraftListUpdate(state.drafts[key]?.partOrder || [], update) } } })),
  setText: (key, text) => set((state) => ({ drafts: { ...state.drafts, [key]: { ...(state.drafts[key] || emptyDraftContent), text } } })),
  setModel: (model) => {
    writeLastModel(model);
    set({ model });
  },
  clear: (key) => set((state) => ({ drafts: { ...state.drafts, [key]: { ...(state.drafts[key] || emptyDraftContent), text: "", partOrder: [], submission: undefined } } })),
  prepareSubmission: (key, input) => {
    const draft = get().drafts[key] || emptyDraftContent;
    const { submission: previous, ...snapshot } = draft;
    const sameConversation = previous && previous.input.projectID === input.projectID && previous.input.widgetDraft === input.widgetDraft;
    const submission = {
      clientRequestID: sameConversation ? previous.clientRequestID : newClientID(),
      clientMessageID: sameConversation && previous.input.text === input.text && JSON.stringify(previous.input.parts) === JSON.stringify(input.parts) ? previous.clientMessageID : newClientID(),
      input,
      snapshot,
    };
    set({ drafts: { ...get().drafts, [key]: { ...draft, submission } } });
    return submission;
  },
  acknowledgeSubmission: (key, submission) => {
    const current = get().drafts[key];
    if (!current || current.submission !== submission) return;
    const { snapshot } = submission;
    // Entries are immutable: additions and replacements (including uploads
    // completing later) belong to the next draft, even if their IDs match.
    const attachments = current.attachments.filter((item) => !snapshot.attachments.includes(item));
    const localFolders = current.localFolders.filter((item) => !snapshot.localFolders.includes(item));
    for (const item of current.attachments) {
      if (!attachments.includes(item) && item.previewURL) URL.revokeObjectURL(item.previewURL);
    }
    const remaining = {
      attachment: new Set(attachments.map((item) => item.id)),
      local_folder: new Set(localFolders.map((item) => item.id)),
      project_reference: new Set<string>(),
    };
    const draft = {
      attachments, localFolders,
      text: current.text === snapshot.text ? "" : current.text,
      partOrder: current.partOrder.filter((item) => remaining[item.type].has(item.id)),
    };
    set((state) => ({ drafts: { ...state.drafts, [key]: draft } }));
    return draft;
  },
}));

function applyDraftListUpdate<T>(current: T[], update: DraftListUpdate<T>) {
  return typeof update === "function" ? update(current) : update;
}

import { create } from "zustand";

import type { ProjectReference, QueuedInput } from "@/api/client";
import { studioReferenceKey, readStudioReferenceMessage, type StudioReference, type StudioReferenceInput } from "@/lib/studioReferences";
import type { DraftAttachment } from "@/lib/attachmentUploads";
import { newClientID } from "@/lib/id";
import type { LocalFolderPath } from "@/lib/localFolders";
import type { DraftPartOrderItem } from "@/lib/submitParts";

export type SessionDraftAttachment = DraftAttachment;

export type DraftSubmission = {
  attachments: SessionDraftAttachment[];
  clientMessageID: string;
  localFolders: LocalFolderPath[];
  partOrder: DraftPartOrderItem[];
  projectReferences: ProjectReference[];
  studioReferences: StudioReference[];
  text: string;
};

export type SessionDraft = DraftSubmission & { submission?: DraftSubmission };

type DraftListUpdate<T> = T[] | ((current: T[]) => T[]);

type SessionDraftState = {
  queueEdits: Record<string, string | undefined>;
  beginQueueEdit: (sessionID: string, input: QueuedInput) => void;
  endQueueEdit: (sessionID: string) => void;
  acknowledgeQueueEdit: (sessionID: string, inputID: string, snapshot: DraftSubmission) => boolean;
  drafts: Record<string, SessionDraft | undefined>;
  clear: (sessionID: string) => SessionDraft;
  discardSession: (sessionID: string) => void;
  prepareSubmission: (draftKey: string) => DraftSubmission;
  acknowledgeSubmission: (draftKey: string, submission: DraftSubmission) => void;
  ensure: (sessionID: string) => SessionDraft;
  setAttachments: (sessionID: string, update: DraftListUpdate<SessionDraftAttachment>) => void;
  setLocalFolders: (sessionID: string, update: DraftListUpdate<LocalFolderPath>) => void;
  setPartOrder: (sessionID: string, update: DraftListUpdate<DraftPartOrderItem>) => void;
  setProjectReferences: (sessionID: string, update: DraftListUpdate<ProjectReference>) => void;
  setStudioReferences: (sessionID: string, update: DraftListUpdate<StudioReference>) => void;
  setText: (sessionID: string, text: string) => void;
};

function newSessionDraft(text = ""): SessionDraft {
  return {
    attachments: [],
    clientMessageID: newClientID(),
    localFolders: [],
    partOrder: [],
    projectReferences: [],
    studioReferences: [],
    text,
  };
}

export const useSessionDraftStore = create<SessionDraftState>((set, get) => ({
  queueEdits: {},
  beginQueueEdit: (sessionID, input) => {
    const key = queuedDraftKey(sessionID, input.clientMessageID);
    const parsed = readStudioReferenceMessage(input.text);
    const draft = newSessionDraft(parsed.text);
    draft.studioReferences = parsed.references;
    // The local edit has its own identity. If the queued item leaves, an
    // explicit send-as-new must not reuse that already accepted message ID.
    for (const part of input.parts || []) {
      if (part.type === "attachment") {
        draft.attachments.push({ id: part.id, name: part.name, size: part.size, status: "uploaded", attachment: part });
        draft.partOrder.push({ type: "attachment", id: part.id });
      } else if (part.type === "local_folder") {
        draft.localFolders.push(part);
        draft.partOrder.push({ type: "local_folder", id: part.id });
      } else if (part.type === "project_reference") {
        draft.projectReferences.push(part);
        draft.partOrder.push({ type: "project_reference", id: part.id });
      }
    }
    set((state) => ({ drafts: { ...state.drafts, [key]: draft }, queueEdits: { ...state.queueEdits, [sessionID]: input.clientMessageID } }));
  },
  acknowledgeQueueEdit: (sessionID, inputID, snapshot) => {
    const state = get();
    const current = state.drafts[queuedDraftKey(sessionID, inputID)];
    // A response may close only the exact edit incarnation and content it sent.
    // Keep the full replacement draft when there are later edits.
    if (state.queueEdits[sessionID] !== inputID || !current || current.clientMessageID !== snapshot.clientMessageID
      || !sameSubmissionContent(current, snapshot)) return false;
    state.endQueueEdit(sessionID);
    return true;
  },
  endQueueEdit: (sessionID) => set((state) => {
    const id = state.queueEdits[sessionID];
    const drafts = { ...state.drafts };
    if (id) {
      const key = queuedDraftKey(sessionID, id);
      for (const item of drafts[key]?.attachments || []) if (item.previewURL) URL.revokeObjectURL(item.previewURL);
      delete drafts[key];
    }
    const queueEdits = { ...state.queueEdits };
    delete queueEdits[sessionID];
    return { drafts, queueEdits };
  }),
  drafts: {},
  discardSession: (sessionID) => set((state) => {
    const drafts = { ...state.drafts };
    for (const key of Object.keys(drafts)) {
      let belongs = key === sessionID;
      if (!belongs) {
        try {
          const owner: unknown = JSON.parse(key);
          belongs = Array.isArray(owner) && owner.length === 2 && owner[0] === sessionID;
        } catch { /* Ordinary conversation IDs are not JSON queue keys. */ }
      }
      if (!belongs) continue;
      for (const item of drafts[key]?.attachments || []) if (item.previewURL) URL.revokeObjectURL(item.previewURL);
      delete drafts[key];
    }
    const queueEdits = { ...state.queueEdits };
    delete queueEdits[sessionID];
    return { drafts, queueEdits };
  }),
  clear: (sessionID) => {
    for (const item of get().drafts[sessionID]?.attachments ?? []) {
      if (item.previewURL) URL.revokeObjectURL(item.previewURL);
    }
    const draft = newSessionDraft();
    set((state) => ({
      drafts: {
        ...state.drafts,
        [sessionID]: draft,
      },
    }));
    return draft;
  },
  prepareSubmission: (draftKey) => {
    const { submission: previous, ...content } = get().ensure(draftKey);
    // A lost response can still mean Core accepted the request. Only an
    // unchanged retry may reuse that request's idempotency key.
    if (previous && sameSubmissionContent(previous, content)) return previous;
    const submission = { ...content, clientMessageID: previous ? newClientID() : content.clientMessageID };
    set((state) => ({ drafts: { ...state.drafts, [draftKey]: { ...submission, submission } } }));
    return submission;
  },
  acknowledgeSubmission: (draftKey, submission) => {
    const current = get().drafts[draftKey];
    if (!current || current.submission !== submission) return;
    // List entries are immutable. Retain additions and replacements made after
    // the snapshot, including previews whose uploads are still in progress.
    const attachments = current.attachments.filter((item) => !submission.attachments.includes(item));
    const localFolders = current.localFolders.filter((item) => !submission.localFolders.includes(item));
    const projectReferences = current.projectReferences.filter((item) => !submission.projectReferences.includes(item));
    const studioReferences = current.studioReferences.filter((item) => !submission.studioReferences.includes(item));
    for (const item of current.attachments) {
      if (!attachments.includes(item) && item.previewURL) URL.revokeObjectURL(item.previewURL);
    }
    const remaining = {
      attachment: new Set(attachments.map((item) => item.id)),
      local_folder: new Set(localFolders.map((item) => item.id)),
      project_reference: new Set(projectReferences.map((item) => item.id)),
    };
    const draft: SessionDraft = {
      attachments, localFolders, projectReferences, studioReferences,
      partOrder: current.partOrder.filter((item) => remaining[item.type].has(item.id)),
      text: current.text === submission.text ? "" : current.text,
      clientMessageID: newClientID(),
    };
    set((state) => ({ drafts: { ...state.drafts, [draftKey]: draft } }));
  },
  ensure: (sessionID) => {
    const existing = get().drafts[sessionID];
    if (existing) {
      return existing;
    }
    const draft = newSessionDraft();
    set((state) => ({
      drafts: {
        ...state.drafts,
        [sessionID]: draft,
      },
    }));
    return draft;
  },
  setAttachments: (sessionID, update) => {
    set((state) => {
      const current = state.drafts[sessionID] ?? newSessionDraft();
      const attachments = applyDraftListUpdate(current.attachments, update);
      if (attachments === current.attachments) return state;
      return {
        drafts: {
          ...state.drafts,
          [sessionID]: {
            ...current,
            attachments,
          },
        },
      };
    });
  },
  setLocalFolders: (sessionID, update) => {
    set((state) => {
      const current = state.drafts[sessionID] ?? newSessionDraft();
      return {
        drafts: {
          ...state.drafts,
          [sessionID]: {
            ...current,
            localFolders: applyDraftListUpdate(current.localFolders, update),
          },
        },
      };
    });
  },
  setPartOrder: (sessionID, update) => {
    set((state) => {
      const current = state.drafts[sessionID] ?? newSessionDraft();
      return {
        drafts: {
          ...state.drafts,
          [sessionID]: {
            ...current,
            partOrder: applyDraftListUpdate(current.partOrder, update),
          },
        },
      };
    });
  },
  setProjectReferences: (sessionID, update) => {
    set((state) => {
      const current = state.drafts[sessionID] ?? newSessionDraft();
      return {
        drafts: {
          ...state.drafts,
          [sessionID]: {
            ...current,
            projectReferences: applyDraftListUpdate(current.projectReferences ?? [], update),
          },
        },
      };
    });
  },
  setStudioReferences: (sessionID, update) => {
    set((state) => {
      const current = state.drafts[sessionID] ?? newSessionDraft();
      return { drafts: { ...state.drafts, [sessionID]: { ...current, studioReferences: applyDraftListUpdate(current.studioReferences, update) } } };
    });
  },
  setText: (sessionID, text) => {
    set((state) => {
      const current = state.drafts[sessionID] ?? newSessionDraft();
      return {
        drafts: {
          ...state.drafts,
          [sessionID]: {
            ...current,
            text,
          },
        },
      };
    });
  },
}));

// Local draft key only; it must never be passed as a business sessionID.
export function queuedDraftKey(sessionID: string, clientMessageID: string) {
  return JSON.stringify([sessionID, clientMessageID]);
}

function applyDraftListUpdate<T>(current: T[], update: DraftListUpdate<T>) {
  return typeof update === "function" ? update(current) : update;
}

function sameSubmissionContent(a: DraftSubmission, b: DraftSubmission) {
  const sameItems = <T,>(left: T[], right: T[]) => left.length === right.length && left.every((item, index) => item === right[index]);
  return a.text === b.text && sameItems(a.attachments, b.attachments) && sameItems(a.localFolders, b.localFolders)
    && sameItems(a.projectReferences, b.projectReferences) && sameItems(a.studioReferences, b.studioReferences)
    && sameItems(a.partOrder, b.partOrder);
}

export function addProjectReferenceToSessionDraft(
  sessionID: string,
  input: Omit<ProjectReference, "id">,
) {
  const state = useSessionDraftStore.getState();
  const editingID = state.queueEdits[sessionID];
  const draftKey = editingID ? queuedDraftKey(sessionID, editingID) : sessionID;
  const draft = state.ensure(draftKey);
  if (
    (draft.projectReferences ?? []).some(
      (reference) =>
        reference.rootID === input.rootID &&
        reference.path === input.path &&
        reference.kind === input.kind &&
        reference.startLine === input.startLine &&
        reference.startColumn === input.startColumn &&
        reference.endLine === input.endLine &&
        reference.endColumn === input.endColumn,
    )
  ) {
    return false;
  }
  const reference: ProjectReference = { ...input, id: newClientID() };
  state.setProjectReferences(draftKey, (current) => [...current, reference]);
  state.setPartOrder(draftKey, (current) => [...current, { type: "project_reference", id: reference.id }]);
  return true;
}

export function addStudioReferenceToSessionDraft(sessionID: string, input: StudioReferenceInput) {
  const state = useSessionDraftStore.getState();
  const editingID = state.queueEdits[sessionID];
  const draftKey = editingID ? queuedDraftKey(sessionID, editingID) : sessionID;
  const draft = state.ensure(draftKey);
  if (draft.studioReferences.some((reference) => studioReferenceKey(reference) === studioReferenceKey(input))) return;
  state.setStudioReferences(draftKey, (current) => [...current, { ...input, id: newClientID() }]);
}

